from pathlib import Path
import hashlib,json,traceback
root=Path.cwd().resolve()
cp=root/'docs/parity/reviews/windows-platform-workload-contract-001.json'
c=json.loads(cp.read_text(encoding='utf-8'))
for pin in c['consumed_files']+c['product_pins']:
    b=(root/pin['path']).read_bytes()
    if len(b)!=pin['bytes'] or hashlib.sha256(b).hexdigest()!=pin['sha256']:raise RuntimeError('Changed input: '+pin['path'])
stage=(root/'build/windows-workload-001/prepare-001').resolve()
if root not in stage.parents:raise RuntimeError('Stage escapes workspace')
stage.mkdir(parents=True,exist_ok=False)
r={'id':'windows-workload.prepare.001','state':'started','acceptance_claim':False,'visible_launches':0,'fixtures':[],
   'contract':{'path':str(cp),'bytes':cp.stat().st_size,'sha256':hashlib.sha256(cp.read_bytes()).hexdigest()}}
def durable():
    (stage/'preparation.json').write_text(json.dumps(r,indent=2,allow_nan=False)+'\n',encoding='utf-8')
durable()
try:
    import imagejxx as ij
    import imagejxx._native as native
    import numpy as np
    site=(root/'build/p06c3-env-ui001/Lib/site-packages').resolve()
    if site not in Path(native.__file__).resolve().parents:raise RuntimeError('Wrong native origin')
    r['native_origin']=str(Path(native.__file__).resolve())
    out=stage/'fixtures';out.mkdir()
    for f in c['fixtures']:
        if f['id'].startswith('F01'):
            z,y,x=np.ogrid[:2,:24,:32];a=(7*z+3*y+x).astype(np.uint16)[...,None]
            cal=ij.SpatialCalibration()
        elif f['id'].startswith('F02'):
            t,ch,z,y,x=np.ogrid[:2,:3,:4,:48,:64]
            a=(4096*t+512*ch+64*z+3*y+x).astype(np.uint16)[...,None]
            cal=ij.SpatialCalibration(**f['calibration'])
        else:
            z,y,x=np.ogrid[:8,:512,:512];a=((17*z+3*y+x)%4096).astype(np.uint16)[...,None]
            cal=ij.SpatialCalibration()
        raw=a.astype('<u2',copy=False).tobytes(order='C')
        if list(a.shape)!=f['shape'] or len(raw)!=f['raw_bytes'] or hashlib.sha256(raw).hexdigest()!=f['raw_sha256']:raise RuntimeError('Literal fixture mismatch')
        owner=ij.Document(ij.Dataset(a,axes=f['axes'],calibration=cal),title=f['id'])
        view=owner.snapshot().display;view.t,view.c=f['initial_tcz'][:2];view.crosshair=f['initial_crosshair_xyz']
        if 'channel_display' in f:view.properties={'channel_display':f['channel_display']}
        owner.set_display(view)
        path=out/f['filename'];ij.save_session(str(path),ij.SessionCapture([owner]))
        decoded=ij.load_session(str(path)).documents[0]
        if decoded.dataset.numpy('TCZYXS').astype('<u2',copy=False).tobytes(order='C')!=raw:raise RuntimeError('Codec changed literal bytes')
        b=path.read_bytes();r['fixtures'].append({'id':f['id'],'path':str(path),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'raw_sha256':f['raw_sha256']})
        if sum(p.stat().st_size for p in stage.rglob('*') if p.is_file())>67108864:raise RuntimeError('Preparation64MiB cap')
        durable()
    r['state']='prepared_fixtures_only_no_platform_execution';durable()
    print(json.dumps({'state':r['state'],'receipt':str(stage/'preparation.json'),'fixture_count':3,'visible_launches':0}))
except BaseException as e:
    r['state']='failed';r['error']=repr(e);r['traceback']=traceback.format_exc();durable();raise
